import { useQuery } from '@tanstack/react-query';
import { useCallback, useEffect, useRef, useState } from 'react';
import { getServerApiBase } from '@/api/server';
import { settingsApi } from '@/api/settings';

interface WorkflowStatusResponse {
  status: 'pending' | 'running' | 'completed' | 'failed';
  result?: {
    html: string;
    metadata?: any;
  };
  error?: string;
}

interface UseDesignSystemPollingReturn {
  isPolling: boolean;
  resultHtml: string;
  workflowId: string;
  status: string;
  progress: number;
  startPolling: (requestData: any) => Promise<string>;
  cancelPolling: () => void;
}

// Helper function to start workflow
async function startWorkflow(
  requestData: any,
  apiToken: string,
  signal: AbortSignal
): Promise<{ workflowId: string; pollUrl: string }> {
  // 构建完整的 API URL - 使用设计系统专用端点
  const apiEndpoint = `${getServerApiBase()}/ai/design-system`;

  // 确保 stream 为 false
  const pollingRequestData = {
    ...requestData,
    request: {
      ...requestData.request,
      stream: false,
    },
  };

  const response = await fetch(apiEndpoint, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      Authorization: `Bearer ${apiToken}`,
    },
    body: JSON.stringify(pollingRequestData),
    signal,
  });

  if (!response.ok) {
    const errorData = await response.json();
    throw new Error(
      errorData.error?.message || `HTTP error! status: ${response.status}`
    );
  }

  const responseData = await response.json();

  // Handle new response structure with success and data fields
  const data = responseData.data || responseData;

  if (!(data.workflowId && data.pollUrl)) {
    throw new Error('No workflow ID or poll URL provided');
  }

  return {
    workflowId: data.workflowId,
    pollUrl: data.pollUrl,
  };
}

// Helper function to compute status text
function getStatusText(
  data: WorkflowStatusResponse | undefined,
  isError: boolean,
  isLoading: boolean
): string {
  if (data?.status === 'running') {
    return 'AI 正在生成设计系统...';
  }
  if (data?.status === 'completed') {
    return 'completed';
  }
  if (data?.status === 'failed') {
    return `Error: ${data.error || '生成失败'}`;
  }
  if (isError) {
    return 'Failed';
  }
  if (isLoading) {
    return 'Connecting...';
  }
  return '';
}

export function useDesignSystemPolling(): UseDesignSystemPollingReturn {
  const [workflowId, setWorkflowId] = useState('');
  const [pollUrl, setPollUrl] = useState<string | null>(null);
  const [progress, setProgress] = useState(0);

  // Get live settings (no reliance on window.zeroySettings)
  const { data: settingsData } = useQuery({
    queryKey: ['settings'],
    queryFn: settingsApi.get,
  });
  const apiToken = settingsData?.settings?.api_token || '';

  const abortControllerRef = useRef<AbortController | null>(null);
  const pollingStartTimeRef = useRef<number>(0);
  const resolveRef = useRef<((value: string) => void) | null>(null);
  const rejectRef = useRef<((err: Error) => void) | null>(null);

  // Poll for workflow status using React Query
  const { data, isLoading, isError, error } = useQuery({
    queryKey: ['design-system-workflow-status', workflowId, apiToken],
    queryFn: async ({ signal }) => {
      if (!(pollUrl && workflowId)) {
        throw new Error('No poll URL available');
      }

      // Check timeout (10 minutes)
      if (Date.now() - pollingStartTimeRef.current > 10 * 60 * 1000) {
        throw new Error('请求超时，请重试');
      }

      const response = await fetch(pollUrl, {
        signal,
        headers: {
          Authorization: `Bearer ${apiToken}`,
        },
      });

      if (!response.ok) {
        throw new Error(`Status check failed: ${response.status}`);
      }

      const result = (await response.json()) as WorkflowStatusResponse;

      // Update progress
      if (result.status === 'running') {
        setProgress((prev) => Math.min(prev + 10, 90));
      } else if (result.status === 'completed') {
        setProgress(100);
      }

      return result;
    },
    enabled: !!pollUrl && !!workflowId,
    refetchInterval: (query) => {
      // Stop polling if completed or failed
      const queryData = query.state.data;
      if (queryData?.status === 'completed' || queryData?.status === 'failed') {
        return false;
      }
      return 3000; // Poll every 3 seconds
    },
    retry: (failureCount, queryError) => {
      // Don't retry on timeout or abort
      if (
        queryError instanceof Error &&
        (queryError.message.includes('超时') ||
          queryError.name === 'AbortError')
      ) {
        return false;
      }
      return failureCount < 3;
    },
  });

  // Handle completion in useEffect to avoid running on every render
  useEffect(() => {
    if (
      data?.status === 'completed' &&
      data.result?.html &&
      resolveRef.current
    ) {
      console.log(
        `Polling completed with HTML: ${data.result.html.substring(0, 100)}...`
      );
      resolveRef.current(data.result.html);
      resolveRef.current = null;
    } else if (data?.status === 'failed' && rejectRef.current) {
      console.error('Polling failed:', data.error);
      rejectRef.current(new Error(data.error || '生成失败'));
      rejectRef.current = null;
    } else if (isError && rejectRef.current) {
      console.error('Polling error:', error);
      rejectRef.current(error as Error);
      rejectRef.current = null;
    }
  }, [data, isError, error]);

  const startPolling = useCallback(
    async (requestData: any): Promise<string> => {
      if (!apiToken) {
        throw new Error('请先配置 API Token');
      }
      // Reset state
      setWorkflowId('');
      setPollUrl(null);
      setProgress(0);
      pollingStartTimeRef.current = Date.now();

      abortControllerRef.current = new AbortController();

      try {
        const startData = await startWorkflow(
          requestData,
          apiToken,
          abortControllerRef.current.signal
        );

        // Set state to trigger polling
        setWorkflowId(startData.workflowId);
        setPollUrl(startData.pollUrl);

        // Return promise that resolves when polling completes
        return new Promise<string>((resolve, reject) => {
          resolveRef.current = resolve;
          rejectRef.current = reject;

          // Set overall timeout (10 minutes)
          setTimeout(
            () => {
              if (resolveRef.current || rejectRef.current) {
                reject(new Error('请求超时'));
                setPollUrl(null);
                setWorkflowId('');
                resolveRef.current = null;
                rejectRef.current = null;
              }
            },
            10 * 60 * 1000
          );
        });
      } catch (err: any) {
        if (err.name === 'AbortError') {
          throw err;
        }
        throw err;
      } finally {
        abortControllerRef.current = null;
      }
    },
    [apiToken]
  );

  const cancelPolling = useCallback(() => {
    abortControllerRef.current?.abort();
    setPollUrl(null);
    setWorkflowId('');
    rejectRef.current?.(new Error('Cancelled by user'));
    resolveRef.current = null;
    rejectRef.current = null;
  }, []);

  // Compute derived state
  const isPolling =
    !!pollUrl &&
    !!workflowId &&
    data?.status !== 'completed' &&
    data?.status !== 'failed';
  const resultHtml = data?.result?.html || '';

  // Compute status
  const status = getStatusText(data, isError, isLoading);

  return {
    isPolling,
    resultHtml,
    workflowId,
    status,
    progress,
    startPolling,
    cancelPolling,
  };
}
