import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query';
import { Download, RefreshCcw, Upload } from 'lucide-react';
import type React from 'react';
import { useRef, useState } from 'react';
import { designSystemApi } from '@/api/design-system';
import { useNotification } from '@/components/notification';
import { DesignSystemAIDialog } from './design-system-ai-dialog';

// Empty state component
interface EmptyStateProps {
  isDragging: boolean;
  onDragEnter: (e: React.DragEvent) => void;
  onDragLeave: (e: React.DragEvent) => void;
  onDragOver: (e: React.DragEvent) => void;
  onDrop: (e: React.DragEvent) => void;
  onGenerateClick: () => void;
  onImportChange: (e: React.ChangeEvent<HTMLInputElement>) => void;
  fileInputRef: React.RefObject<HTMLInputElement | null>;
}

const EmptyState: React.FC<EmptyStateProps> = ({
  isDragging,
  onDragEnter,
  onDragLeave,
  onDragOver,
  onDrop,
  onGenerateClick,
  onImportChange,
  fileInputRef,
}) => (
  // biome-ignore lint/a11y/useSemanticElements: This is a drag-drop zone, not a button
  <div
    aria-label="拖放区域"
    className={`flex flex-col items-center justify-center rounded-lg border-2 border-dashed p-12 transition-colors ${
      isDragging ? 'border-blue-400 bg-blue-50' : 'border-gray-300 bg-white'
    }`}
    onDragEnter={onDragEnter}
    onDragLeave={onDragLeave}
    onDragOver={onDragOver}
    onDrop={onDrop}
    role="button"
    tabIndex={0}
  >
    <div className="text-center">
      <svg
        aria-hidden="true"
        className={`mx-auto h-12 w-12 transition-colors ${
          isDragging ? 'text-blue-500' : 'text-gray-400'
        }`}
        fill="none"
        stroke="currentColor"
        viewBox="0 0 24 24"
      >
        <path
          d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"
          strokeLinecap="round"
          strokeLinejoin="round"
          strokeWidth={2}
        />
      </svg>
      <h3 className="mt-2 font-medium text-gray-900 text-sm">
        {isDragging ? '松开以上传文件' : '还没有设计系统'}
      </h3>
      <p className="mt-1 text-gray-500 text-sm">
        {isDragging
          ? '将 HTML 文件拖放到这里'
          : '拖放 HTML 文件、使用 AI 生成或导入现有文件'}
      </p>
      {!isDragging && (
        <div className="mt-6 flex items-center justify-center gap-3">
          <button
            className="inline-flex items-center rounded-md bg-blue-600 px-4 py-2 font-medium text-sm text-white shadow-sm transition-colors hover:bg-blue-700"
            onClick={onGenerateClick}
            type="button"
          >
            生成设计系统
          </button>
          <span className="text-gray-500">或</span>
          <label className="inline-flex cursor-pointer items-center gap-2 rounded-md bg-gray-50 px-3 py-2 text-gray-700 text-sm transition-colors hover:bg-gray-100">
            <Upload className="h-4 w-4" />
            导入 HTML
            <input
              accept=".html"
              className="hidden"
              onChange={onImportChange}
              ref={fileInputRef}
              type="file"
            />
          </label>
        </div>
      )}
    </div>
  </div>
);

export const DesignTab: React.FC = () => {
  const [showDialog, setShowDialog] = useState(false);
  const [savingMessage, setSavingMessage] = useState<string>('');
  const [isDragging, setIsDragging] = useState(false);
  const queryClient = useQueryClient();
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { notify } = useNotification();

  // Fetch design system HTML
  const { data, isLoading } = useQuery({
    queryKey: ['design-system'],
    queryFn: designSystemApi.get,
  });

  // Clear design system mutation
  const clearMutation = useMutation({
    mutationFn: designSystemApi.clear,
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['design-system'] });
    },
  });

  const hasContent = data?.hasContent ?? false;
  const html = data?.html ?? '';

  // Save design system mutation
  const saveMutation = useMutation({
    mutationFn: async (newHtml: string) => {
      setSavingMessage('正在保存设计系统...');

      // 给用户一点时间看到消息
      await new Promise((resolve) => setTimeout(resolve, 100));
      setSavingMessage('正在提取字体信息...');

      const result = await designSystemApi.update(newHtml);

      setSavingMessage('正在下载字体文件...');
      // 给后端一些时间处理字体
      await new Promise((resolve) => setTimeout(resolve, 500));

      return result;
    },
    onSuccess: () => {
      setSavingMessage('');
      notify('success', '设计系统已更新，字体已下载');
      queryClient.invalidateQueries({ queryKey: ['design-system'] });
    },
    onError: () => {
      setSavingMessage('');
      notify('error', '保存失败，请重试');
    },
  });

  // Handle download
  const handleDownload = () => {
    const blob = new Blob([html], { type: 'text/html' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `design-system-${new Date().toISOString().split('T')[0]}.html`;
    document.body.appendChild(a);
    a.click();
    document.body.removeChild(a);
    URL.revokeObjectURL(url);
    notify('success', '设计系统已下载');
  };

  // Process file (shared between input and drag-drop)
  const processFile = (file: File) => {
    if (!file.name.endsWith('.html')) {
      notify('error', '请上传 HTML 文件');
      return;
    }

    const reader = new FileReader();
    reader.onload = (e) => {
      const content = e.target?.result as string;
      if (content) {
        saveMutation.mutate(content);
      }
    };
    reader.onerror = () => {
      notify('error', '文件读取失败');
    };
    reader.readAsText(file);
  };

  // Handle import
  const handleImport = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) {
      return;
    }

    processFile(file);

    // Reset input
    if (fileInputRef.current) {
      fileInputRef.current.value = '';
    }
  };

  // Handle drag events
  const handleDragEnter = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(true);
  };

  const handleDragOver = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
  };

  const handleDragLeave = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);
  };

  const handleDrop = (e: React.DragEvent) => {
    e.preventDefault();
    e.stopPropagation();
    setIsDragging(false);

    const file = e.dataTransfer.files?.[0];
    if (!file) {
      return;
    }

    processFile(file);
  };

  if (isLoading) {
    return (
      <div className="flex items-center justify-center p-8">
        <div className="animate-spin">
          <RefreshCcw className="h-6 w-6 text-gray-400" />
        </div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      <div className="relative rounded-lg bg-white p-6 shadow-sm">
        {/* Loading overlay */}
        {saveMutation.isPending && (
          <div className="absolute inset-0 z-50 flex items-center justify-center rounded-lg bg-black/50">
            <div className="rounded-lg bg-white p-6 shadow-lg">
              <div className="mb-4 flex justify-center">
                <div className="h-12 w-12 animate-spin rounded-full border-4 border-gray-200 border-t-primary-600" />
              </div>
              <p className="text-center font-medium text-gray-900">
                {savingMessage || '处理中...'}
              </p>
              <p className="mt-2 text-center text-gray-600 text-sm">
                这可能需要一些时间，请耐心等待...
              </p>
            </div>
          </div>
        )}
        <div className="mb-4 flex items-center justify-between">
          <div>
            <h2 className="font-medium text-lg">设计系统</h2>
            <p className="mt-1 text-gray-600 text-sm">
              {hasContent
                ? '编译 CSS 时会自动使用此设计系统，确保所有页面的设计统一性。'
                : '创建一个设计系统来确保您网站的视觉一致性。'}
            </p>
          </div>
          {hasContent && (
            <button
              className="rounded-md bg-red-50 px-3 py-2 text-red-700 text-sm transition-colors hover:bg-red-100"
              disabled={clearMutation.isPending}
              onClick={() => {
                if (confirm('确定要清空设计系统吗？此操作不可撤销。')) {
                  clearMutation.mutate();
                }
              }}
              type="button"
            >
              {clearMutation.isPending ? '清空中...' : '清空设计系统'}
            </button>
          )}
        </div>

        {hasContent ? (
          <div className="space-y-4">
            <div className="flex justify-between">
              <div className="flex gap-2">
                <button
                  className="inline-flex items-center gap-2 rounded-md bg-gray-50 px-3 py-2 text-gray-700 text-sm transition-colors hover:bg-gray-100"
                  onClick={handleDownload}
                  type="button"
                >
                  <Download className="h-4 w-4" />
                  下载 HTML
                </button>
                <label className="inline-flex cursor-pointer items-center gap-2 rounded-md bg-gray-50 px-3 py-2 text-gray-700 text-sm transition-colors hover:bg-gray-100">
                  <Upload className="h-4 w-4" />
                  导入 HTML
                  <input
                    accept=".html"
                    className="hidden"
                    onChange={handleImport}
                    ref={fileInputRef}
                    type="file"
                  />
                </label>
              </div>
              <button
                className="rounded-md bg-blue-50 px-3 py-2 text-blue-700 text-sm transition-colors hover:bg-blue-100"
                onClick={() => setShowDialog(true)}
                type="button"
              >
                重新生成
              </button>
            </div>
            <div className="overflow-hidden rounded-lg border border-gray-200">
              <iframe
                className="h-[800px] w-full"
                sandbox="allow-scripts"
                srcDoc={html}
                title="Design System Preview"
              />
            </div>
          </div>
        ) : (
          <EmptyState
            fileInputRef={fileInputRef}
            isDragging={isDragging}
            onDragEnter={handleDragEnter}
            onDragLeave={handleDragLeave}
            onDragOver={handleDragOver}
            onDrop={handleDrop}
            onGenerateClick={() => setShowDialog(true)}
            onImportChange={handleImport}
          />
        )}
      </div>

      {showDialog && (
        <DesignSystemAIDialog
          isOpen={showDialog}
          onClose={() => setShowDialog(false)}
          onSuccess={() => {
            setShowDialog(false);
            queryClient.invalidateQueries({ queryKey: ['design-system'] });
          }}
        />
      )}
    </div>
  );
};
