import { useMutation, useQuery } from '@tanstack/react-query';
import { Send, Sparkles, X } from 'lucide-react';
import type React from 'react';
import { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { designSystemApi } from '@/api/design-system';
import { settingsApi } from '@/api/settings';
import { useNotification } from '@/components/notification';
import { CodeDisplay } from '@/editor/components/ai-assistant/shared/code-display';
import { FakeStreamDisplay } from '@/editor/components/ai-assistant/shared/fake-stream-display';
import { useAIModelAvailability } from '@/hooks/use-ai-model-availability';
import type { ModelListResult, UnifiedModel } from '@/lib/ai-config-provider';
import { extractAiCredentials } from '@/lib/ai-credentials';
import {
  chooseInitialModel,
  createModelStorageKey,
  ensureSelectionExists,
  persistModelSelection,
} from '@/lib/model-selection';
import { ModelSelect } from '@/settings/components/ai-settings/model-select';
import { useDesignSystemPolling } from '@/settings/hooks/use-design-system-polling';

interface DesignSystemAIDialogProps {
  isOpen: boolean;
  onClose: () => void;
  onSuccess: () => void;
}

interface Message {
  id: string;
  role: 'user' | 'assistant';
  content: string;
  html?: string;
}

export const DesignSystemAIDialog: React.FC<DesignSystemAIDialogProps> = ({
  isOpen,
  onClose,
  onSuccess,
}) => {
  const { notify } = useNotification();
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputValue, setInputValue] = useState('');
  const [models, setModels] = useState<UnifiedModel[]>([]);
  const [selectedModel, setSelectedModel] = useState<string>('');
  const [modelError, setModelError] = useState('');
  const [currentBaseUrl, setCurrentBaseUrl] = useState('');
  const [savingMessage, setSavingMessage] = useState<string>('');
  const messagesEndRef = useRef<HTMLDivElement>(null);
  const hasInitializedModel = useRef(false);

  // Use polling hook
  const { isPolling, startPolling, cancelPolling } = useDesignSystemPolling();

  // Live settings
  const { data: settingsData } = useQuery({
    queryKey: ['settings'],
    queryFn: settingsApi.get,
  });

  useEffect(() => {
    const baseUrl = settingsData?.settings?.base_url;
    if (baseUrl && !currentBaseUrl) {
      setCurrentBaseUrl(baseUrl);
    }
  }, [settingsData?.settings?.base_url, currentBaseUrl]);

  const aiCredentials = useMemo(
    () => extractAiCredentials(settingsData?.settings),
    [settingsData?.settings]
  );

  const {
    result: modelResult,
    loading: isLoadingModels,
    error: availabilityError,
  } = useAIModelAvailability({
    enabled: isOpen && aiCredentials.hasCredentials,
    credentials: settingsData?.settings || null,
  });

  const syncSelection = useCallback(
    (modelList: UnifiedModel[], storageBase: string | null) => {
      const storageKey = storageBase
        ? createModelStorageKey(storageBase)
        : null;

      const applySelection = (modelId: string | null) => {
        setSelectedModel(modelId ?? '');
        persistModelSelection(storageKey, modelId);
      };

      if (!hasInitializedModel.current) {
        const saved = storageKey ? localStorage.getItem(storageKey) : null;
        const initial = chooseInitialModel(modelList, {
          saved,
          defaultModel: settingsData?.settings?.model,
          currentSelection: selectedModel,
        });
        applySelection(initial);
        hasInitializedModel.current = true;
        return;
      }

      const ensured = ensureSelectionExists(modelList, selectedModel);
      if (ensured !== (selectedModel || null)) {
        applySelection(ensured);
      }
    },
    [selectedModel, settingsData?.settings?.model]
  );

  const getModelListErrorMessage = useCallback((result: ModelListResult) => {
    if (result.source === 'none') {
      return (
        result.serverErrorMessage ||
        result.localErrorMessage ||
        '无法获取模型列表，请检查配置'
      );
    }
    if (result.source === 'local' && result.serverStatus === 'error') {
      return result.serverErrorMessage
        ? `${result.serverErrorMessage}（已回退到本地配置）`
        : '服务端配置不可用，已回退到本地配置';
    }
    return '';
  }, []);

  const handleFetchResult = useCallback(
    (result: ModelListResult, localBase: string) => {
      const resolvedBase = result.baseUrl || localBase;
      if (resolvedBase && resolvedBase !== currentBaseUrl) {
        hasInitializedModel.current = false;
        setCurrentBaseUrl(resolvedBase);
      }

      const modelsOrSuggestions =
        result.models && result.models.length > 0
          ? result.models
          : (result.suggestions || []).map((s) => ({ id: s, name: s }));
      setModels(modelsOrSuggestions);
      const storageBase = resolvedBase || currentBaseUrl || localBase || '';
      syncSelection(modelsOrSuggestions, storageBase || null);
      const msg =
        getModelListErrorMessage(result) ||
        (result.listingSupported === false
          ? '上游不支持列出模型，请手动选择或输入模型 ID'
          : '');
      setModelError(msg);
    },
    [currentBaseUrl, getModelListErrorMessage, syncSelection]
  );

  // Load AI models
  useEffect(() => {
    if (!isOpen) {
      return;
    }

    if (!aiCredentials.hasCredentials) {
      setModels([]);
      setModelError('请先配置 API URL/Key 或将凭据上传到服务端。');
      return;
    }

    if (availabilityError) {
      setModels([]);
      setModelError(availabilityError);
      return;
    }

    if (modelResult) {
      handleFetchResult(modelResult, aiCredentials.baseUrl);
    }
  }, [
    isOpen,
    aiCredentials.hasCredentials,
    aiCredentials.baseUrl,
    availabilityError,
    modelResult,
    handleFetchResult,
  ]);

  // Auto-scroll to bottom
  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, []);

  // Save design system mutation
  const saveMutation = useMutation({
    mutationFn: async (html: string) => {
      setSavingMessage('正在保存设计系统...');

      // 给用户一点时间看到消息
      await new Promise((resolve) => setTimeout(resolve, 100));
      setSavingMessage('正在提取字体信息...');

      const result = await designSystemApi.update(html);

      setSavingMessage('正在下载字体文件...');
      // 给后端一些时间处理字体
      await new Promise((resolve) => setTimeout(resolve, 500));

      return result;
    },
    onSuccess: () => {
      setSavingMessage('');
      notify('success', '设计系统已保存，字体已下载');
      onSuccess();
    },
    onError: () => {
      setSavingMessage('');
      notify('error', '保存失败，请重试');
    },
  });

  const handleModelChange = useCallback(
    (value: string) => {
      setSelectedModel(value);
      hasInitializedModel.current = true;
      const storageBase = currentBaseUrl || settingsData?.settings?.base_url;
      if (!storageBase) {
        return;
      }
      const storageKey = createModelStorageKey(storageBase);
      localStorage.setItem(storageKey, value);
    },
    [currentBaseUrl, settingsData?.settings?.base_url]
  );

  const renderModelSelector = () => {
    if (models.length > 0) {
      return (
        <ModelSelect
          isLoading={isLoadingModels}
          models={models}
          onChange={handleModelChange}
          placeholder="请选择 AI 模型"
          value={selectedModel}
        />
      );
    }

    if (isLoadingModels) {
      return <div className="text-gray-500 text-sm">模型列表加载中...</div>;
    }

    return (
      <div className="text-red-600 text-sm">
        {modelError || '无可用模型，请检查配置或重试'}
      </div>
    );
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputValue.trim() || isPolling) {
      return;
    }

    const userMessage: Message = {
      id: `user-${Date.now()}`,
      role: 'user',
      content: inputValue,
    };
    setMessages((prev) => [...prev, userMessage]);
    setInputValue('');

    try {
      const requestData = {
        config: {
          api_key: settingsData?.settings?.api_key || '',
          base_url: settingsData?.settings?.base_url || '',
          model: selectedModel || settingsData?.settings?.model || 'gpt-4o',
        },
        request: {
          requirements: inputValue, // 主要需求描述
          additional_context: settingsData?.settings?.additional_context || '', // 可选额外上下文
        },
      };

      const generatedHtml = await startPolling(requestData);

      console.log(
        `Generated HTML received: ${generatedHtml?.substring(0, 100)}...`
      );

      // Check if the response has content
      if (!generatedHtml) {
        throw new Error('No content generated');
      }

      const aiMessage: Message = {
        id: `ai-${Date.now()}`,
        role: 'assistant',
        content: '设计系统生成完成！您可以预览并选择插入。',
        html: generatedHtml,
      };
      console.log('Adding AI message with HTML to messages');
      setMessages((prev) => [...prev, aiMessage]);
    } catch (error: any) {
      console.error('Generation error:', error);
      notify('error', error.message || '生成失败，请检查 AI 配置并重试');
    }
  };

  const handleInsert = (html: string) => {
    saveMutation.mutate(html);
  };

  if (!isOpen) {
    return null;
  }

  return (
    <div className="fixed inset-0 z-9999 flex items-center justify-center p-4">
      <button
        aria-label="Close dialog"
        className="absolute inset-0 bg-black/50"
        onClick={onClose}
        type="button"
      />

      <div className="relative z-10 flex h-[80vh] w-full max-w-6xl flex-col rounded-lg bg-white shadow-xl">
        {/* Loading overlay */}
        {saveMutation.isPending && (
          <div className="absolute inset-0 z-50 flex items-center justify-center rounded-lg bg-black/50">
            <div className="rounded-lg bg-white p-6 shadow-lg">
              <div className="mb-4 flex justify-center">
                <div className="h-12 w-12 animate-spin rounded-full border-4 border-gray-200 border-t-primary-600" />
              </div>
              <p className="text-center font-medium text-gray-900">
                {savingMessage || '处理中...'}
              </p>
            </div>
          </div>
        )}

        {/* Header */}
        <div className="flex items-center justify-between border-b px-6 py-4">
          <div className="flex items-center gap-2">
            <Sparkles className="h-5 w-5 text-primary-600" />
            <h2 className="font-semibold text-lg">AI 设计系统生成器</h2>
          </div>
          <button
            aria-label="Close"
            className="rounded-lg p-1.5 text-gray-400 transition-colors hover:bg-gray-100 hover:text-gray-600"
            onClick={onClose}
            type="button"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        {/* Model selector */}
        <div className="border-b px-6 py-3">
          <div className="max-w-xs">
            <div className="mb-1.5 block font-medium text-gray-700 text-sm">
              AI 模型
            </div>
            {renderModelSelector()}
          </div>
        </div>

        {/* Chat area */}
        <div className="flex flex-1 overflow-hidden">
          {/* Messages */}
          <div className="flex flex-1 flex-col">
            <div className="flex-1 space-y-4 overflow-y-auto p-6">
              {messages.length === 0 && !isPolling && (
                <div className="text-center text-gray-500">
                  <p className="mb-2 font-medium">开始创建您的设计系统</p>
                  <p className="text-sm">
                    描述您想要的设计风格，AI 将为您生成完整的设计系统
                  </p>
                </div>
              )}

              {messages.map((message) => (
                <div
                  className={`flex ${
                    message.role === 'user' ? 'justify-end' : 'justify-start'
                  }`}
                  key={message.id}
                >
                  <div
                    className={`max-w-[70%] rounded-lg px-4 py-2 ${
                      message.role === 'user'
                        ? 'bg-primary-600 text-white'
                        : 'bg-gray-100 text-gray-900'
                    }`}
                  >
                    <p className="whitespace-pre-wrap">{message.content}</p>
                    {message.html && (
                      <div className="mt-3">
                        <div className="mb-2 font-medium text-sm">
                          生成的设计系统代码：
                        </div>
                        <CodeDisplay
                          code={message.html}
                          onInsert={handleInsert}
                          showInsertButton={!saveMutation.isPending}
                        />
                      </div>
                    )}
                  </div>
                </div>
              ))}

              {/* Fake stream display */}
              <FakeStreamDisplay isActive={isPolling} />

              <div ref={messagesEndRef} />
            </div>

            {/* Input form */}
            <form className="border-t p-4" onSubmit={handleSubmit}>
              <div className="flex gap-2">
                <input
                  className="flex-1 rounded-lg border border-gray-300 px-4 py-2 focus:border-primary-500 focus:outline-none focus:ring-2 focus:ring-primary-500/20"
                  disabled={isPolling}
                  onChange={(e) => setInputValue(e.target.value)}
                  placeholder="描述您想要的设计风格，例如：现代简约风格，使用蓝色主题..."
                  type="text"
                  value={inputValue}
                />
                {isPolling ? (
                  <button
                    className="rounded-lg bg-red-600 px-4 py-2 text-white transition-colors hover:bg-red-700"
                    onClick={cancelPolling}
                    type="button"
                  >
                    取消
                  </button>
                ) : (
                  <button
                    className="rounded-lg bg-primary-600 px-4 py-2 text-white transition-colors hover:bg-primary-700 disabled:bg-gray-300"
                    disabled={!inputValue.trim()}
                    type="submit"
                  >
                    <Send className="h-5 w-5" />
                  </button>
                )}
              </div>
            </form>
          </div>
        </div>
      </div>
    </div>
  );
};
