import { apiClient } from './client';

export interface DesignSystemResponse {
  html: string;
  hasContent: boolean;
}

export const designSystemApi = {
  get: () => apiClient.get<DesignSystemResponse>('/settings/design-system'),

  update: (html: string) =>
    apiClient.post<DesignSystemResponse>('/settings/design-system', { html }),

  clear: () =>
    apiClient.delete<DesignSystemResponse>('/settings/design-system'),
};
